function getSum(nums) {
  const MOD = 1000000007;
  let upCount = 1;
  let upSum = nums[0];
  let downCount = 1;
  let downSum = nums[0];
  let total = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const value = nums[i];
    if (value - nums[i - 1] === 1) {
      upCount++;
      upSum = (upSum + upCount * value) % MOD;
    } else {
      upCount = 1;
      upSum = value;
    }
    if (value - nums[i - 1] === -1) {
      downCount++;
      downSum = (downSum + downCount * value) % MOD;
    } else {
      downCount = 1;
      downSum = value;
    }
    total = (total + upSum + downSum - value) % MOD;
  }
  return total;
}

