function getSum(nums) {
  // From every start, walk right while each step keeps the same difference of +1 (or of -1),
  // adding the value of every piece on the way. The exact total stays small enough to reduce once at the end.
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    total += nums[start];
    for (const step of [1, -1]) {
      let piece = nums[start];
      for (let end = start + 1; end < nums.length && nums[end] - nums[end - 1] === step; end++) {
        piece += nums[end];
        total += piece;
      }
    }
  }
  return total % 1000000007;
}

