function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const top = large ? 100000 : [6, 20, 100000][Math.floor(rand() * 3)];
  // keep is the chance that the current direction goes on; large inputs build long runs so the total wraps the modulus.
  const keep = large ? [0.9, 0.995, 0.9995][Math.floor(rand() * 3)] : 0.6;
  const nums = [1 + Math.floor(rand() * top)];
  let step = rand() < 0.5 ? 1 : -1;
  for (let i = 1; i < n; i++) {
    if (rand() > keep) step = [1, -1, 0][Math.floor(rand() * 3)];
    let value = nums[i - 1] + step;
    if (step === 0 || value < 1 || value > top) value = 1 + Math.floor(rand() * top);
    nums.push(value);
  }
  return [nums];
}
